def f(A):
    H,W=len(A),len(A[0])
    C=Counter(x for r in A for x in r)
    order=[c for c,_ in C.most_common()]
    bg,barc,mk=order[0],order[1],order[-1]
    barcells={(i,j) for i in range(H) for j in range(W) if A[i][j]==barc}
    comps=components(barcells,H,W)
    bars=[]
    for idx,comp in enumerate(comps):
        rs=[p[0] for p in comp]; cs=[p[1] for p in comp]
        if max(rs)-min(rs)>=max(cs)-min(cs):
            bars.append(('v',min(rs),max(rs),min(cs),max(cs)))
        else:
            bars.append(('h',min(cs),max(cs),min(rs),max(rs)))
    out=[r[:] for r in A]
    mkpos=[(i,j) for i in range(H) for j in range(W) if A[i][j]==mk]
    def seg_to(t,i,j):
        # t: ('v',ro,r1,c1,c2) or ('h',)
        if t[0]=='v':
            # horizontal ray along row i toward bar cols [c1,c2]
            lo,hi=min(c1,c2),max(c1,c2)
            if j<lo: return [(i,k) for k in range(j+1,lo)]
            if j>hi: return [(i,k) for k in range(hi+1,j)]
        else:
            lo,hi=min(r1,r1),max(r1,r1)
            lo,hi=t[2],t[3]
            if i<lo: return [(k,j) for k in range(i+1,lo)]
            if i>hi: return [(k,j) for k in range(hi+1,i)]
        return []
    def mark_line(r,c,axis):
        if axis=='h':
            for j in range(W):
                if (r,j) not in barcells: out[r][j]=mk
        else:
            for i in range(H):
                if (i,c) not in barcells: out[i][c]=mk
    for i,j in mkpos:
        ts=[idx for idx,t in enumerate(bars) if (t[0]=='v' and t[2]<=i<=t[3]) or (t[0]=='h' and t[2]<=j<=t[3])]
        if not ts: ts=[0]
        t=bars[ts[0]]
        s=seg_to(t,i,j)
        for p in s: out[p[0]][p[1]]=mk
        out[i][j]=4
        # shifted full line: map farthest marker into the other bar's span edge
        other=[b for b in bars if b is not t][0]
        if t[0]=='v':
            # horizontal lines at row marker+delta, delta so max(marker_rows)+delta = other span end
            dr=other[3]-max(mi for mi,_ in mkpos)
        else:
            dc=other[3]-max(mc for _,mc in mkpos)
            dr=dc=0
        axis='h' if t[0]=='v' else 'v'
        for i,j in mkpos:
            rr=i+dr if axis=='h' else j+dr
            cc=j       if axis=='h' else i+dr
            mark_line(rr,cc,axis)
    return out

