from collections import Counter
def solve(A):
    H,W=len(A),len(A[0])
    cnt=Counter(x for r in A for x in r)
    order=sorted(cnt.keys(),key=lambda c:-cnt[c])
    bg,bar,mk=order[0],order[1],order[-1]
    out=[r[:] for r in A]
    seen=set(); bars=[]
    for i in range(H):
        j=0
        while j<W:
            if A[i][j]==bar:
                k=j
                while k<W and A[i][k]==bar: k+=1
                if k-j>1: bars.append(('h',i,j,k-1)); j=k
                else: j+=1
            else: j+=1
    for j in range(W):
        i=0
        while i<H:
            if A[i][j]==bar:
                k=i
                while k<H and A[k][j]==bar: k+=1
                if k-i>1: bars.append(('v',j,i,k-1)); i=k
                else: i+=1
            else: i+=1
    mpos=[(i,j) for i in range(H) for j in range(W) if A[i][j]==mk]
    def axis_dist(b,(i,j)):
        if b[0]=='v': return abs(j-b[1])
        return abs(i-b[2])
    for i,j in mpos:
        out[i][j]=4
        con=None
        for b in bars:
            if b[0]=='v' and b[2]<=i<=b[3]: con=(b,'vert'); break
            if b[0]=='h' and b[2]<=j<=b[3]: con=(b,'horz'); break
        if con is not None:
            src,_=con
            tgt=[b for b in bars if b is not src][0]
            if src[0]=='v':
                o=i-src[2]                     # offset within source row-span
                rmap=tgt[2]+o                  # mapped row in target's col span -> full horizontal line
                # ray toward source bar: horizontal, toward its column
                if src[1]<j: 
                    for c in range(src[1],j): out[i][c]=mk
                else:
                    for c in range(j+1,src[1]+1): out[i][c]=mk
                # full line at mapped row
                for c in range(W):
                    if (rmap,c) not in {(q,p) for q,p in [(q,tgt[1]) for q in range(tgt[2],tgt[3]+1)]}:
                        out[rmap][c]=mk
            else:
                o=j-src[3]
                cmap=tgt[3]+o                  # mapped col
                if tgt[2]<j:
                    for r in range(tgt[2],j): out[r][j]=mk
                else:
                    for r in range(j+1,tgt[2]+1): out[r][j]=mk
                # full column at mapped col
                for r in range(H):
                    if (r,cmap) not in {(q,p) for q,p in [(tgt[2],p) for p in range(tgt[3],tgt[4]+1)]}:
                        out[r][cmap]=mk
        else:
            bgt=min(bars,key=lambda b,axis_dist(b,(i,j)))
            dta=lambda b:axis_dist(b,(i,j))
            tgt=min(bars,key=dta)
            if tgt[0]=='v':
                if tgt[1]<j:
                    for c in range(tgt[1],j): out[i][c]=mk
                else:
                    for c in range(j+1,tgt[1]+1): out[i][c]=mk
            else:
                if tgt[2]<i:
