def analyze(name):
    A=G[name+' input']; O=G[name+' output']
    h=len(A); w=len(A[0])
    cntA=Counter(x for row in A for x in row); cntO=Counter(x for row in O for x in row)
    bgA=min(c for c,n in cntA.items() if n>10)
    print(f'== {name} {h}x{w}, bgA={bgA}')
    # find components of non-bg, non-4
    def comps(A,c):
        seen=set(); out=[]
        for i in range(h):
            for j in range(w):
                if A[i][j]==c and (i,j) not in seen:
                    stack=[(i,j)]; comp=[]
                    while stack:
                        p,q=stack.pop()
                        if (p,q) in seen: continue
                        seen.add((p,q)); comp.append((p,q))
                        for dp,dq in ((1,0),(-1,0),(0,1),(0,-1)):
                            np,nq=p+dp,q+dq
                            if 0<=np<h and 0<=nq<w and A[np][nq]==c: stack.append((np,nq))
                    out.append(comp)
        return out
    cs_A=comps(A,bgA); cs_O=comps(O,bgA)
    print('in comp sizes',sorted((len(c) for c in cs_A),reverse=True)[:6])
